import {makePath,linked,uid} from './core.js';
import {componentShape} from './shapes.js';
import {modifier} from './effects.js';
export const streetResources=[
...Object.entries({patch:'Bolsillo parche',jean:'Bolsillo jean',back:'Bolsillo trasero',cargo:'Bolsillo cargo',cargoFlap:'Cargo con solapa',zip:'Bolsillo con cierre',diagonalZip:'Cierre diagonal',welt:'Bolsillo ojal',side:'Bolsillo lateral',hidden:'Bolsillo oculto',utility:'Bolsillo utilitario'}).map(([key,name])=>['pockets','pocket-'+key,name]),
...Object.entries({classic:'Clásica',oversized:'Oversized',deep:'Profunda',double:'Doble capa',cross:'Cuello cruzado',high:'Cuello alto',balaclava:'Balaclava',panelled:'Con paneles'}).map(([key,name])=>['hoods','hood-'+key,'Capucha '+name]),
['cords','cordBraided','Cordón trenzado'],['cords','cordElastic','Cordón elástico'],['fabric','stackSlight','Stack suave'],['fabric','stackMedium','Stack medio'],['fabric','stackHeavy','Stack fuerte'],['fabric','pleatKnife','Pliegue cuchillo'],['fabric','pleatBox','Pliegue tabla'],['fabric','dart','Pinza'],['fabric','tuck','Alforza'],['fabric','kneeSingle','Rodilla curva'],['fabric','kneeDouble','Rodilla doble'],['fabric','kneeTechnical','Rodilla técnica'],['fabric','quiltHorizontal','Quilt horizontal'],['fabric','quiltDiamond','Quilt rombos'],['fabric','ripSmart','Rasgadura editable'],['fabric','distressSmart','Desgaste procedural'],['hardware','buckle','Hebilla']];
export function smartResource(key){if(key.startsWith('pocket-')){let style=key.slice(7),c={kind:'pocket',style,width:style==='utility'?110:86,height:style==='utility'?125:100,radius:4,stitchOffset:4,flap:style==='cargoFlap',flapHeight:22,gussetDepth:style.startsWith('cargo')?6:0,openingAngle:style==='diagonalZip'?25:0,zipPosition:25,stitchType:'simple'};if(style==='cargoFlap')c.style='cargo';const o=makePath(streetResources.find(r=>r[1]===key)[2],'M 0 0 L 1 0','white',{component:c,category:'detail',semanticType:'pocket'});Object.assign(o,componentShape(c));o.modifiers=[modifier('stitch',{offset:c.stitchOffset})];return [o];}
if(key.startsWith('hood-')){const style=key.slice(5),c={kind:'hood',style,width:style==='oversized'?130:100,height:style==='deep'?145:110,depth:style==='deep'?70:45,opening:style==='balaclava'?.35:.7,overlap:style==='cross'?18:0,panels:style==='panelled'?3:1,layers:style==='double'?2:1};if(style==='high')c.height=135;const o=makePath(streetResources.find(r=>r[1]===key)[2],'M 0 0 L 1 0','#fff',{component:c,category:'structure',semanticType:'hood'});Object.assign(o,componentShape(c));return [o];}
if(key==='cordBraided'||key==='cordElastic'){const s=makePath('Guía de cordón','M 0 0 C 10 30 -10 70 0 110','none',{hidden:true,category:'construction'});return [s,linked(s,'cord',{cordStyle:key==='cordBraided'?'braided':'elastic',cordWidth:5,category:'detail'})];}
if(key.startsWith('stack')){const o=makePath('Muestra de Stack','M 0 0 L 90 0 L 90 140 L 0 140 Z','#fff',{category:'structure'});o.modifiers=[modifier('fabricFall',stackPreset(key))];return [o];}
if(key.startsWith('pleat')||key.startsWith('quilt')||key==='distressSmart'){const o=makePath('Panel de construcción','M 0 0 L 100 0 L 100 100 L 0 100 Z','#fff',{category:'construction'});o.modifiers=[modifier(key.startsWith('quilt')?'quilt':key.startsWith('pleat')?'pleat':'distress',key.startsWith('quilt')?{pattern:key==='quiltDiamond'?'diamond':'horizontal'}:{pleatType:key==='pleatBox'?'box':'knife'})];return [o];}
if(key==='dart'||key==='tuck')return [makePath(key==='dart'?'Pinza':'Alforza',key==='dart'?'M 0 0 L 10 80 L 20 0':'M 0 0 L 0 90 L 8 90 L 8 0','none',{category:'construction'})];
if(key.startsWith('knee')){const rows=key==='kneeSingle'?1:key==='kneeDouble'?2:3;return Array.from({length:rows},(_,i)=>makePath('Panel de rodilla','M 0 '+(i*15)+' Q 55 '+(i*15+20)+' 110 '+(i*15),'none',{category:'construction'}));}
if(key==='ripSmart'){const o=makePath('Rasgadura','M 0 0 L 70 0','none',{category:'detail'});o.modifiers=[modifier('raw',{length:8,intensity:3,spacing:4,seed:7})];return [o];}
if(key==='buckle')return [makePath('Hebilla','M 0 0 L 35 0 L 35 25 L 0 25 Z','#fff',{category:'detail',modifiers:[modifier('parallel',{offset:4})]})];return null;}
export function stackPreset(key){return key==='stackSlight'?{intensity:2,foldCount:2,length:50}:key==='stackHeavy'?{intensity:9,foldCount:5,length:100}:{intensity:5,foldCount:3,length:70};}
